function loadInterlinear(){tabPanel.innerHTML='<div class="logos-loading">Loading original-language study layer…</div>';if(currentPassage&&currentPassage.testament==='NT'){if(!greekReady){clear(tabPanel);tabPanel.appendChild(el('div','logos-error','The production Greek New Testament layer is temporarily unavailable. The English Douay-Rheims passage remains available above.'));return;}var ref=currentReference;getJson('/api/logos/greek/interlinear?reference='+encodeURIComponent(ref)).then(function(greek){if(currentReference!==ref||currentTab!=='interlinear')return;renderCombinedParallel(currentPassage,greek);renderGreekInterlinear(greek);setStatus('Live · '+ref+' · English + Greek semantic interlinear');return loadSemanticStudy(ref);}).catch(function(err){if(currentReference!==ref||currentTab!=='interlinear')return;clear(tabPanel);tabPanel.appendChild(el('div','logos-error','Could not load the production Greek New Testament interlinear for this passage.'));setStatus('Greek interlinear unavailable · '+ref,true);});return;}getJson('/api/logos/interlinear?reference='+encodeURIComponent(currentReference)).then(renderInterlinear).catch(function(err){clear(tabPanel);tabPanel.appendChild(el('div','logos-error',passageError(err)));});}
