function study(reference){reference=String(reference||'').trim();if(!reference)return;currentReference=reference;referenceInput.value=reference;setStatus('Loading '+reference+'…');getJson('/api/logos/passage?reference='+encodeURIComponent(reference)).then(function(data){currentPassage=data;renderParallel(data);currentReference=data.reference||reference;referenceInput.value=currentReference;setStatus('Live · '+currentReference);loadTab();}).catch(function(err){currentPassage=null;clear(parallelRoot);parallelRoot.appendChild(el('div','logos-error',passageError(err)));setStatus('Could not load '+reference,true);});}

