function openBookChapters(book){if(!book)return;readerBook=book;readerChapter=null;var browser=document.getElementById('logosBookBrowser'),panel=document.getElementById('logosChapterPanel'),reader=document.getElementById('logosReaderPanel'),title=document.getElementById('logosChapterBookTitle'),grid=document.getElementById('logosChapterGrid');browser.hidden=true;reader.hidden=true;panel.hidden=false;title.textContent=book.name;clear(grid);for(var i=1;i<=Number(book.chapter_count||0);i++){(function(chapter){var button=el('button','',String(chapter));button.type='button';button.setAttribute('aria-label',book.name+' chapter '+chapter);button.addEventListener('click',function(){openReaderChapter(book,chapter);});grid.appendChild(button);})(i);}}
