function openVerseSheet(row){selectedReaderVerse=row;var sheet=document.getElementById('logosVerseSheet');document.getElementById('logosVerseSheetRef').textContent=row.reference;document.getElementById('logosVerseSheetText').textContent=row.text;var related=document.getElementById('logosVerseTheology');clear(related);related.appendChild(theologyGuide(row.reference));updateVerseBookmarkAction();updateVerseHighlightAction();document.getElementById('logosVerseShareStatus').textContent='';sheet.hidden=false;sheet.setAttribute('aria-hidden','false');if(!sheet.classList.contains('is-inline'))document.body.classList.add('logos-sheet-open');sheet.querySelector('.logos-sheet-card').scrollTop=0;if(sheet.classList.contains('is-inline'))setTimeout(function(){sheet.scrollIntoView({block:'start'});},80);else try{sheet.querySelector('.logos-sheet-close').focus({preventScroll:true});}catch(e){sheet.querySelector('.logos-sheet-close').focus();}}
function bindVerseTap(button,row){var start=null,suppressClickUntil=0;button.addEventListener('touchstart',function(event){var touch=event.touches&&event.touches[0];start=touch?{x:touch.clientX,y:touch.clientY,time:Date.now()}:null;},{passive:true});button.addEventListener('touchcancel',function(){start=null;},{passive:true});button.addEventListener('touchend',function(event){var touch=event.changedTouches&&event.changedTouches[0];if(!start||!touch)return;var tapped=Math.abs(touch.clientX-start.x)<14&&Math.abs(touch.clientY-start.y)<14&&Date.now()-start.time<800;start=null;suppressClickUntil=Date.now()+800;if(!tapped)return;event.preventDefault();openVerseSheet(row);},{passive:false});button.addEventListener('click',function(){if(Date.now()>=suppressClickUntil)openVerseSheet(row);});}
