function artForShare(){var chosen=selectedArt(),art=window.MercyLogosArt;if(chosen!=='random')return chosen;var choices=art.themes.map(function(row){return row[0];}).filter(function(id){return id!==lastSharedArt;});var bytes=new Uint32Array(1);if(window.crypto&&window.crypto.getRandomValues)window.crypto.getRandomValues(bytes);else bytes[0]=Math.floor(Math.random()*4294967296);lastSharedArt=choices[bytes[0]%choices.length];return lastSharedArt;}
