function cardLines(ctx,value,width,size){ctx.font=size+'px Georgia, serif';var lines=[],line='';String(value||'').split(/\s+/).forEach(function(word){var next=line?line+' '+word:word;if(ctx.measureText(next).width>width&&line){lines.push(line);line=word;}else line=next;});if(line)lines.push(line);return lines;}
